messages.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "oneOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "const": "image_url"
        }
      },
      "required": [
        "type",
        "image_url"
      ]
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "const": "input_audio"
        }
      },
      "required": [
        "type",
        "input_audio"
      ]
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "input_video"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "video_url"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "const": "file"
        }
      },
      "required": [
        "type",
        "file"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    },
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "url"
  ]
}
